package com.whatsaas.automation.engine;
import com.fasterxml.jackson.databind.JsonNode; import com.whatsaas.automation.domain.WorkflowExecution; import com.whatsaas.common.config.MessagingProperties; import com.whatsaas.whatsapp.application.MessageQueuedEvent; import com.whatsaas.whatsapp.domain.WhatsAppMessage; import com.whatsaas.whatsapp.infrastructure.WhatsAppMessageRepository; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.stereotype.Component;
@Component public class WhatsAppTextNodeProcessor implements WorkflowNodeProcessor{private final WhatsAppMessageRepository messages;private final RabbitTemplate rabbit;private final MessagingProperties messaging;public WhatsAppTextNodeProcessor(WhatsAppMessageRepository m,RabbitTemplate r,MessagingProperties p){messages=m;rabbit=r;messaging=p;}public String type(){return "whatsapp_text";}public NodeResult process(WorkflowExecution e,JsonNode n,JsonNode c){JsonNode d=n.path("data");String to=value(d.path("recipient").asText(),c,"/message/from");String phone=value(d.path("phoneNumberId").asText(),c,"/message/phoneNumberId");String body=value(d.path("body").asText(),c,"/message/body");WhatsAppMessage msg=messages.save(new WhatsAppMessage(e.getTenantId(),null,phone,to,body));rabbit.convertAndSend(messaging.exchange(),messaging.messageRoutingKey(),new MessageQueuedEvent(e.getTenantId(),msg.getId()));return NodeResult.next("{\"messageId\":"+msg.getId()+"}");}private String value(String v,JsonNode c,String pointer){return v==null||v.isBlank()?c.at(pointer).asText():v.replace("{{message.body}}",c.at("/message/body").asText()).replace("{{message.from}}",c.at("/message/from").asText());}}
